import inspect

_ARG_NAMES = set(inspect.signature(TrainingArguments.__init__).parameters)

def make_training_args(**kwargs):
    '''Build TrainingArguments, silently dropping options this version does not have.'''
    if "eval_strategy" in kwargs and "eval_strategy" not in _ARG_NAMES:
        kwargs["evaluation_strategy"] = kwargs.pop("eval_strategy")   # older name
    dropped = [k for k in kwargs if k not in _ARG_NAMES]
    for k in dropped:
        kwargs.pop(k)
    if dropped:
        print("(ignored options not in this version:", ", ".join(dropped) + ")")
    return TrainingArguments(**kwargs)

print("TrainingArguments accepts", len(_ARG_NAMES), "options in this version")
